import{_ as i,o as e,c as a,a2 as r}from"./chunks/framework.BUwdTBzS.js";const c=JSON.parse('{"title":"SQL_官方规范","description":"sql 代码规范","frontmatter":{"title":"SQL_官方规范","description":"sql 代码规范"},"headers":[],"relativePath":"rules/SQL_官方规范.md","filePath":"rules/SQL_官方规范.md","lastUpdated":null}'),t={name:"rules/SQL_官方规范.md"};function o(n,l,s,u,d,h){return e(),a("div",null,[...l[0]||(l[0]=[r('<blockquote><p>📄 本页由源文件 <code>rules/SQL_官方规范.mdc</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="sql-官方规范" tabindex="-1">SQL_官方规范 <a class="header-anchor" href="#sql-官方规范" aria-label="Permalink to &quot;SQL_官方规范&quot;">​</a></h1><p>你是一个专业的SQL助手，所有SQL代码必须严格遵循以下编码规范。</p><h2 id="规范等级约定" tabindex="-1">规范等级约定 <a class="header-anchor" href="#规范等级约定" aria-label="Permalink to &quot;规范等级约定&quot;">​</a></h2><ul><li><strong>必须（Mandatory）</strong>：必须采用</li><li><strong>推荐（Preferable）</strong>：理应采用，但如有特殊情况，可以不采用</li></ul><h2 id="命名规范" tabindex="-1">命名规范 <a class="header-anchor" href="#命名规范" aria-label="Permalink to &quot;命名规范&quot;">​</a></h2><h3 id="通用规则" tabindex="-1">通用规则 <a class="header-anchor" href="#通用规则" aria-label="Permalink to &quot;通用规则&quot;">​</a></h3><p><strong>必须（Mandatory）</strong>：</p><ul><li>不允许使用保留关键字，使用一致的、描述意义的命名</li><li>在命名只使用字母、数字和下划线，不包含空格或其他特殊字符</li><li>命名以字母开头，不能以数字、下划线开头，不能以下划线结尾</li><li>不允许在名字中出现连续下划线</li><li>不允许使用驼峰命名，建议使用下划线分割单词</li></ul><p><strong>推荐（Preferable）</strong>：</p><ul><li>尽量不要用拼音，用贴切的英文单词</li><li>尽量避免使用缩写词，除非这个缩写词是简明易懂、约定俗成的</li></ul><h3 id="库命名" tabindex="-1">库命名 <a class="header-anchor" href="#库命名" aria-label="Permalink to &quot;库命名&quot;">​</a></h3><p><strong>必须（Mandatory）</strong>：</p><ul><li>全部小写命名，禁止出现大写</li><li>数据库名称不要超过30个字符，简洁明了，能够清晰地表达库的用途或内容</li></ul><p><strong>推荐（Preferable）</strong>：</p><ul><li>按照业务模块、产品线和访问权限隔离需求，创建不同的数据库</li></ul><h3 id="表命名" tabindex="-1">表命名 <a class="header-anchor" href="#表命名" aria-label="Permalink to &quot;表命名&quot;">​</a></h3><p><strong>必须（Mandatory）</strong>：</p><ul><li>全部小写命名，禁止出现大写</li><li>表名不超过50个字符，简洁、清晰、易懂，能够表达表的用途和内容</li></ul><p><strong>推荐（Preferable）</strong>：</p><ul><li>表名符合统一的数仓规范，包括分层、主题域、存储策略、存储周期等信息</li><li>使用通用的数仓分层（ods、dwd、dws、dim、ads、tmp）做为表前缀</li><li>表名不能和列名同名</li></ul><h3 id="字段命名" tabindex="-1">字段命名 <a class="header-anchor" href="#字段命名" aria-label="Permalink to &quot;字段命名&quot;">​</a></h3><p><strong>必须（Mandatory）</strong>：</p><ul><li>全部小写命名，禁止出现大写</li><li>字段名不超过32个字符，简洁、清晰、易懂</li></ul><p><strong>推荐（Preferable）</strong>：</p><ul><li>建议各表之间相同意义的字段应同名，并且一定使用相同的字段类型</li><li>尽量给每个字段添加注释，枚举型需指明主要值的含义</li><li>尽量不要出现uid、pid、cid这样的缩写，字段名尽量做到可以正确理解</li></ul><h2 id="编码格式规范" tabindex="-1">编码格式规范 <a class="header-anchor" href="#编码格式规范" aria-label="Permalink to &quot;编码格式规范&quot;">​</a></h2><h3 id="通用规范" tabindex="-1">通用规范 <a class="header-anchor" href="#通用规范" aria-label="Permalink to &quot;通用规范&quot;">​</a></h3><p><strong>必须（Mandatory）</strong>：</p><ul><li>关键字必须保持一致，全部大写或者全部小写，禁止大小写混用</li><li>每行不超过120个字符，禁止所有SQL代码全部堆在一两行</li><li>使用4个空格而不是TAB作为1个缩进量，所有的缩进均为1个缩进量的整数倍，同一层级的SQL代码保持一致的缩进量来代表层次结构</li><li>在等号、不等于号、大于号、大于等于号、小于号、小于等于号前后增加一个空格</li><li>在逗号后面加一个空格</li><li>在成对的单引号或双引号前后增加1个空格，除非其在括号中，或其后面是逗号或分号</li></ul><p><strong>推荐（Preferable）</strong>：</p><ul><li>建议每个子语句尽量不要超过100行（过长不易维护，且容易出错。若必须可以考虑with写法）</li><li>下列情况建议换行： <ul><li>对子查询换行</li><li>代码长度超过120个字符长度时，选择合适的关键字（case when、and、or等）进行换行</li><li>新起一行编写一个完整的DQL、DDL、DML语句</li><li>在分号后（分隔语句以提高可读性）</li></ul></li><li>将代码分隔成相关联的多个部分，帮助提高大段代码的可读性</li></ul><h3 id="代码注释规范" tabindex="-1">代码注释规范 <a class="header-anchor" href="#代码注释规范" aria-label="Permalink to &quot;代码注释规范&quot;">​</a></h3><p><strong>必须（Mandatory）</strong>：</p><ul><li>每一个实现完整统计、可独立运行的SQL语句，均需要增加代码头部注释</li><li>头部注释必须包括：程序名称、功能描述、创建人/修改人、创建/修改日期</li><li>使用--开头进行单行注释，使用/<em>...</em>/包围进行多行注释</li><li>注释应简洁明了，直接说明代码的意图和逻辑，避免冗余，与代码保持一致更新</li></ul><p><strong>推荐（Preferable）</strong>：</p><ul><li>代码头部注释中增加目标表、数据源表信息、需求来源、修改历史记录</li><li>建议每个嵌套子查询在select前添加注释说明该部分代码主要作用</li><li>任何使用常量、魔法数，或硬编码的地方均要注释</li><li>为复杂的字符串处理、时间计算、UDF函数等增加注释说明</li><li>对复杂或特殊的业务统计逻辑增加注释说明</li></ul><h3 id="代码缩进规范" tabindex="-1">代码缩进规范 <a class="header-anchor" href="#代码缩进规范" aria-label="Permalink to &quot;代码缩进规范&quot;">​</a></h3><p><strong>必须（Mandatory）</strong>：</p><ul><li><p>SELECT子句规范：</p><ul><li>在关键字select、from、where、group by、having、order by、limit关键字的前后换行</li><li>在join（包括left join、right join、outer join、inner join）和on关键字的前后面换行</li><li>在where后面的每一个and前换行</li><li>显式声明当前查询结果保留的每一个字段名，不要使用select *（select * 影响对代码逻辑的理解，且影响引擎性能和查询效率）</li><li>在字段列表前后换行，每一行书写一个字段</li><li>对字段别名，必须显式使用as关键字</li><li>select分层编排，每一层的多个select语句对齐缩进量，下一层select语句增加一级缩进量</li></ul></li><li><p>JOIN和UNION子语句规范：</p><ul><li>from和join包含的子查询语句，换行后书写左括号（{）和右花括号（}），并保持同一对花括号缩进量一致</li><li>同一级的join查询，其join和on关键字保持缩进量一致</li><li>在union或union all的前后换行，前后并列的代码块保持缩进量一致</li></ul></li><li><p>CASE WHEN子语句规范：</p><ul><li>每个case when...else..end语句尽量在1行内缩写，如果语句较长时需要换行</li><li>换行缩写时：case和end关键字与其同级的子语句保持一致的缩进量</li><li>新起一行并增加一级缩进量缩写when子语句，同一级的when和else语句保持缩进量对齐</li><li>多个case when进行嵌套时，下一级的case when子语句在上一级的then后换行、增加一级缩进量后缩写</li></ul></li><li><p>WITH子句规范：</p><ul><li>在with后换行写as和别名</li><li>新起一行写左括号（{）和右花括号（}），并保持同一对花括号缩进量一致</li><li>多个with子查询时，换行写另一个as和别名</li></ul></li></ul><p><strong>推荐（Preferable）</strong>：</p><ul><li>SELECT子语句规范： <ul><li>把逗号写在select字段的前面（避免丢逗号，且方便批量编辑）</li></ul></li><li>JOIN和UNION子语句规范： <ul><li>在union语句前后增加一个空行，用于分割并列的代码块</li><li>尽量不要用笛卡尔积</li><li>尽量避免使用union，而是使用union all（前者对结果进行去重，后者不去重）</li><li>大表关联小表时候使用map join（尽量使用sql hint指定）</li></ul></li><li>WITH子语句规范： <ul><li>使用with来将模块化、可共用的代码抽取出来，使代码更简洁</li><li>对with语句子查询的别名应该具有描述性，可被理解</li></ul></li></ul><h3 id="ddl和dml语句规范" tabindex="-1">DDL和DML语句规范 <a class="header-anchor" href="#ddl和dml语句规范" aria-label="Permalink to &quot;DDL和DML语句规范&quot;">​</a></h3><p><strong>必须（Mandatory）</strong>：</p><ul><li><p>CREATE语句规范：</p><ul><li>将create语句和表名写在第一行，换行后书写左括号（{）和右花括号（}）</li><li>规范化库、表、字段命名</li><li>每一个表字段独立一行，给每个字段写字段说明comment</li><li>表注释关键字comment前换行，给表写comment</li><li>显式声明表的存储格式</li></ul></li><li><p>ALTER语句规范：</p><ul><li>将alter语句和表名写在第一行，换行后书写每一种修改操作的语句</li></ul></li><li><p>INSERT语句规范：</p><ul><li>将insert语句和表名、插入分区写在第一行，换行后书写DQL语句</li></ul></li></ul><p><strong>推荐（Preferable）</strong>：</p><ul><li>CREATE语句规范： <ul><li>非临时表包含表的数仓分层、主题域、存储策略、存储周期等信息</li><li>数据类型不允许完全使用string类型，以免数据加工环节的数据质量问题无法及时暴露 <ul><li>带小数点数据使用double类型（金额也可以使用厘，存bigint），需要注释或字段说明单位</li><li>字符类数据使用string类型</li><li>mpp引擎需要考虑准确的数据类型，减少内存消耗</li></ul></li><li>表存储格式尽量使用parquet、orcfile，同时加上压缩关键字</li><li>大表需要按规范设置合理的生命周期</li></ul></li><li>DROP语句规范： <ul><li>尽量避免使用drop语句，需要double check（删数据危险操作）</li></ul></li><li>ALTER语句规范： <ul><li>谨慎删除列，确保不会影响现有数据和查询</li><li>修改列类型，确保新类型兼容旧类型，避免数据丢失或类型转换错误</li></ul></li><li>INSERT语句规范： <ul><li>注意insert和insert overwrite的区别，前者追加数据到表中，后者覆盖原有数据</li><li>对分区表，insert语句显式声明插入的分区</li><li>insert语句显式指定具体的字段名称，因为数据库的字段数量和顺序可能会被修改</li></ul></li></ul><h2 id="最佳实践要点" tabindex="-1">最佳实践要点 <a class="header-anchor" href="#最佳实践要点" aria-label="Permalink to &quot;最佳实践要点&quot;">​</a></h2><ol><li>优先使用规范化的命名，全小写+下划线分割</li><li>必须为SQL添加完整的头部注释和关键逻辑注释</li><li>严格按照缩进规范格式化代码，提高可读性</li><li>避免使用SELECT *，明确指定所需字段</li><li>合理使用分区和索引，优化查询性能</li></ol>',49)])])}const g=i(t,[["render",o]]);export{c as __pageData,g as default};
